// NPPI Copy variants: packed AC4 / masked (MR) / channel-conversion copies.
//
// Covers nppiCopy_*_{C2R,C1MR,C3MR,C4MR,AC4MR,AC4R,C1C2R,C1C3R,C1C4R,
// C2C1R,C3C1R,C3CR,C4C1R,C4CR} for the dtypes added by package p2.1b.
// Plain packed C1R/C3R/C4R and the planar/inter-conversion copies live in
// nppi_copy.cu; this file only adds the variants that share the generic
// STRIDE/COPY templates below.
//
// GPU kernels and *_Ctx_impl entry points.  The public wrappers (outside
// extern "C", generated by macros) live in nppi_copy_variants.cpp.
#include "npp.h"
#include <cstdint>
#include <cuda_runtime.h>

// ---------------------------------------------------------------------------
// Kernels
// ---------------------------------------------------------------------------

// Copy COPY channels per pixel, STRIDE channels between pixels.  This single
// template covers plain packed copies, AC4R (COPY=3 of STRIDE=4) and the
// "selected channel" copies C3CR/C4CR (COPY=1 of STRIDE=3/4).
template <typename T, int STRIDE, int COPY>
__global__ void nppiCopy_px_kernel(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, int width, int height) {
  int x = blockIdx.x * blockDim.x + threadIdx.x;
  int y = blockIdx.y * blockDim.y + threadIdx.y;
  if (x >= width || y >= height) return;
  const T *sr = (const T *)((const char *)pSrc + y * nSrcStep);
  T *dr = (T *)((char *)pDst + y * nDstStep);
#pragma unroll
  for (int c = 0; c < COPY; c++) dr[x * STRIDE + c] = sr[x * STRIDE + c];
}

// Insert channel: source is a contiguous single-channel image, destination is
// one selected channel of a multi-channel image (DSTSTRIDE channels per pixel).
template <typename T, int DSTSTRIDE>
__global__ void nppiCopy_C1Cx_kernel(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, int width, int height) {
  int x = blockIdx.x * blockDim.x + threadIdx.x;
  int y = blockIdx.y * blockDim.y + threadIdx.y;
  if (x >= width || y >= height) return;
  const T *sr = (const T *)((const char *)pSrc + y * nSrcStep);
  T *dr = (T *)((char *)pDst + y * nDstStep);
  dr[x * DSTSTRIDE] = sr[x];
}

// Extract channel: source is one selected channel of a multi-channel image
// (SRCSTRIDE channels per pixel), destination is a single-channel image.
template <typename T, int SRCSTRIDE>
__global__ void nppiCopy_CxC1_kernel(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, int width, int height) {
  int x = blockIdx.x * blockDim.x + threadIdx.x;
  int y = blockIdx.y * blockDim.y + threadIdx.y;
  if (x >= width || y >= height) return;
  const T *sr = (const T *)((const char *)pSrc + y * nSrcStep);
  T *dr = (T *)((char *)pDst + y * nDstStep);
  dr[x] = sr[x * SRCSTRIDE];
}

// Masked copy: copy a pixel only where the 8u mask value for that pixel is
// non-zero. COPY channels copied at STRIDE per pixel (AC4MR copies 3 of 4).
template <typename T, int STRIDE, int COPY>
__global__ void nppiCopy_MR_kernel(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, const Npp8u *pMask,
                                   int nMaskStep, int width, int height) {
  int x = blockIdx.x * blockDim.x + threadIdx.x;
  int y = blockIdx.y * blockDim.y + threadIdx.y;
  if (x >= width || y >= height) return;
  const Npp8u *mask_row = (const Npp8u *)((const char *)pMask + y * nMaskStep);
  if (mask_row[x] == 0) return;
  const T *sr = (const T *)((const char *)pSrc + y * nSrcStep);
  T *dr = (T *)((char *)pDst + y * nDstStep);
#pragma unroll
  for (int c = 0; c < COPY; c++) dr[x * STRIDE + c] = sr[x * STRIDE + c];
}

// ---------------------------------------------------------------------------
// Run helpers (launch, clear stale error, empty ROI short-circuit)
// ---------------------------------------------------------------------------
template <typename T, int STRIDE, int COPY>
static NppStatus px_run(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, int width, int height,
                        cudaStream_t stream) {
  if (width == 0 || height == 0) return NPP_NO_ERROR;
  dim3 b(16, 16);
  dim3 g((width + b.x - 1) / b.x, (height + b.y - 1) / b.y);
  (void)cudaGetLastError();
  nppiCopy_px_kernel<T, STRIDE, COPY><<<g, b, 0, stream>>>(pSrc, nSrcStep, pDst, nDstStep, width, height);
  return cudaGetLastError() == cudaSuccess ? NPP_NO_ERROR : NPP_CUDA_KERNEL_EXECUTION_ERROR;
}

template <typename T, int DSTSTRIDE>
static NppStatus c1cx_run(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, int width, int height,
                          cudaStream_t stream) {
  if (width == 0 || height == 0) return NPP_NO_ERROR;
  dim3 b(16, 16);
  dim3 g((width + b.x - 1) / b.x, (height + b.y - 1) / b.y);
  (void)cudaGetLastError();
  nppiCopy_C1Cx_kernel<T, DSTSTRIDE><<<g, b, 0, stream>>>(pSrc, nSrcStep, pDst, nDstStep, width, height);
  return cudaGetLastError() == cudaSuccess ? NPP_NO_ERROR : NPP_CUDA_KERNEL_EXECUTION_ERROR;
}

template <typename T, int SRCSTRIDE>
static NppStatus cxc1_run(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, int width, int height,
                          cudaStream_t stream) {
  if (width == 0 || height == 0) return NPP_NO_ERROR;
  dim3 b(16, 16);
  dim3 g((width + b.x - 1) / b.x, (height + b.y - 1) / b.y);
  (void)cudaGetLastError();
  nppiCopy_CxC1_kernel<T, SRCSTRIDE><<<g, b, 0, stream>>>(pSrc, nSrcStep, pDst, nDstStep, width, height);
  return cudaGetLastError() == cudaSuccess ? NPP_NO_ERROR : NPP_CUDA_KERNEL_EXECUTION_ERROR;
}

template <typename T, int STRIDE, int COPY>
static NppStatus mr_run(const T *pSrc, int nSrcStep, T *pDst, int nDstStep, const Npp8u *pMask, int nMaskStep,
                        int width, int height, cudaStream_t stream) {
  if (width == 0 || height == 0) return NPP_NO_ERROR;
  dim3 b(16, 16);
  dim3 g((width + b.x - 1) / b.x, (height + b.y - 1) / b.y);
  (void)cudaGetLastError();
  nppiCopy_MR_kernel<T, STRIDE, COPY><<<g, b, 0, stream>>>(pSrc, nSrcStep, pDst, nDstStep, pMask, nMaskStep, width,
                                                           height);
  return cudaGetLastError() == cudaSuccess ? NPP_NO_ERROR : NPP_CUDA_KERNEL_EXECUTION_ERROR;
}

// ---------------------------------------------------------------------------
// *_Ctx_impl instantiations (public wrappers are macro-generated in the .cpp)
// ---------------------------------------------------------------------------

// Plain / AC4 / selected-channel (C3CR, C4CR) impl.
#define DEF_PX_IMPL(CTYPE, SUF, STRIDE, COPY)                                                                          \
  extern "C" NppStatus nppiCopy_##SUF##_Ctx_impl(const CTYPE *pSrc, int nSrcStep, CTYPE *pDst, int nDstStep,           \
                                                 NppiSize oSizeROI, NppStreamContext nppStreamCtx) {                   \
    return px_run<CTYPE, STRIDE, COPY>(pSrc, nSrcStep, pDst, nDstStep, oSizeROI.width, oSizeROI.height,                \
                                       nppStreamCtx.hStream);                                                          \
  }

// Insert channel C1Cx (src single-channel -> dst selected channel).
#define DEF_C1CX_IMPL(CTYPE, SUF, DSTSTRIDE)                                                                           \
  extern "C" NppStatus nppiCopy_##SUF##_Ctx_impl(const CTYPE *pSrc, int nSrcStep, CTYPE *pDst, int nDstStep,           \
                                    NppiSize oSizeROI, NppStreamContext nppStreamCtx) {                                \
    return c1cx_run<CTYPE, DSTSTRIDE>(pSrc, nSrcStep, pDst, nDstStep, oSizeROI.width, oSizeROI.height,                 \
                                      nppStreamCtx.hStream);                                                           \
  }

// Extract channel CxC1 (src multi-channel -> dst single-channel).
#define DEF_CXC1_IMPL(CTYPE, SUF, SRCSTRIDE)                                                                           \
  extern "C" NppStatus nppiCopy_##SUF##_Ctx_impl(const CTYPE *pSrc, int nSrcStep, CTYPE *pDst, int nDstStep,           \
                                    NppiSize oSizeROI, NppStreamContext nppStreamCtx) {                                \
    return cxc1_run<CTYPE, SRCSTRIDE>(pSrc, nSrcStep, pDst, nDstStep, oSizeROI.width, oSizeROI.height,                 \
                                      nppStreamCtx.hStream);                                                           \
  }

// Masked copy (with pMask / nMaskStep).
#define DEF_MR_IMPL(CTYPE, SUF, STRIDE, COPY)                                                                          \
  extern "C" NppStatus nppiCopy_##SUF##_Ctx_impl(const CTYPE *pSrc, int nSrcStep, CTYPE *pDst, int nDstStep,           \
                                    NppiSize oSizeROI, const Npp8u *pMask, int nMaskStep,                              \
                                    NppStreamContext nppStreamCtx) {                                               \
    return mr_run<CTYPE, STRIDE, COPY>(pSrc, nSrcStep, pDst, nDstStep, pMask, nMaskStep, oSizeROI.width,               \
                                       oSizeROI.height, nppStreamCtx.hStream);                                          \
  }


